from solution import fizzbuzz


def test_small():
    assert fizzbuzz(5) == ["1", "2", "Fizz", "4", "Buzz"]


def test_fifteen():
    assert fizzbuzz(15)[-1] == "FizzBuzz"
    assert fizzbuzz(15)[8] == "Fizz"
    assert len(fizzbuzz(15)) == 15


def test_zero():
    assert fizzbuzz(0) == []

from solution import word_count


def test_basic():
    assert word_count("Hello, hello world") == {"hello": 2, "world": 1}
    assert word_count("The cat. The dog!") == {"the": 2, "cat": 1, "dog": 1}


def test_edges():
    assert word_count("") == {}
    assert word_count("it's") == {"it": 1, "s": 1}
    assert word_count("a1 A1 b2") == {"a1": 2, "b2": 1}
